int pqcp_runtime_recovery_policy_lookup(
	enum pqcp_runtime_recovery_condition condition,
	enum pqcp_runtime_command_kind command,
	struct pqcp_runtime_recovery_policy_decision *decision)
{
	if (condition < PQCP_RUNTIME_RECOVERY_HEALTHY ||
	    condition >= PQCP_RUNTIME_RECOVERY_CONDITION_COUNT ||
	    command < PQCP_RUNTIME_COMMAND_NONE ||
	    command >= PQCP_RUNTIME_COMMAND_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = runtime_recovery_catalog[condition][command];
	return 0;
}

int pqcp_runtime_recovery_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_RUNTIME_RECOVERY_CONDITION_COUNT;
	     ++condition) {
		for (size_t command = 0U;
		     command < PQCP_RUNTIME_POLICY_COMMAND_COUNT;
		     ++command) {
			const struct pqcp_runtime_recovery_policy_decision
				*entry =
					&runtime_recovery_catalog
						[condition][command];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->command != command ||
			    entry->directive >
				PQCP_RUNTIME_RECOVERY_TERMINATE ||
			    entry->next_state <
				PQCP_RUNTIME_POLICY_UNINITIALIZED ||
			    entry->next_state >
				PQCP_RUNTIME_POLICY_TERMINATED ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
